import copy
import math

import numpy as np

from src.bench_rectangle import fits, parking_pose
from src.grounding import resolve
from src.task_config import BENCH_RECT_CFG

MAX_RUN_STEPS = 4


def _targets(world, seg):
    """The world xy of a manipulation step's objects (each phrase must resolve to one entry), or None if one does not."""
    out = []
    for o in seg.get("objects", []):
        found = resolve(world, o["phrase"])
        if len(found) != 1:
            return None
        out.append(np.asarray(found[0].position, float)[:2])
    return out


def plan_runs(tagged, world, yaw, rect, max_steps=MAX_RUN_STEPS):
    """Groups the plan into runs of manipulation steps that one parking spot serves.

    Args:
        tagged (dict): The tagged plan.
        world (WorldModel): For the objects' positions.
        yaw (float): The base heading that faces the bench, radians.
        rect (dict): The bench rectangle.
        max_steps (int): The most manipulation steps in one run. Defaults to 4.

    Returns:
        list of dict: One per run: "nav" (the segment indices of the navigation steps the run covers: the first moves, the others are null), "steps" (the manipulation segment indices), "targets" ((N, 2) world xy),
        "pose" ((x, y, yaw) parked), "fits" (bool), "unresolved" (a phrase did not resolve to one entry).
    """
    runs, cur = [], None
    for i, seg in enumerate(tagged["segments"]):
        if seg["type"] == "navigation":
            if cur is not None and cur["steps"] and not cur["unresolved"]:
                joined = _extend(cur, tagged, i, world, yaw, rect, max_steps)
                if joined:
                    cur["nav"].append(i)
                    continue
            cur = {"nav": [i], "steps": [], "targets": [], "unresolved": False}
            runs.append(cur)
        else:
            if cur is None:
                cur = {"nav": [], "steps": [], "targets": [], "unresolved": False}
                runs.append(cur)
            t = _targets(world, seg)
            cur["steps"].append(i)
            if t is None:
                cur["unresolved"] = True
            else:
                cur["targets"] += t
    for r in runs:
        r["targets"] = np.array(r["targets"]).reshape(-1, 2)
        if len(r["targets"]):
            r["pose"], r["fits"] = parking_pose(rect, r["targets"], yaw)
        else:
            r["pose"], r["fits"] = None, False
    return runs


def _extend(cur, tagged, nav_index, world, yaw, rect, max_steps):
    """Whether the manipulation steps after navigation step `nav_index` can join the current run (the union of the targets fits from one spot, at most max_steps steps). Changes nothing."""
    nxt = []
    for j in range(nav_index + 1, len(tagged["segments"])):
        if tagged["segments"][j]["type"] == "navigation":
            break
        nxt.append(j)
    if not nxt or len(cur["steps"]) + len(nxt) > max_steps:
        return False
    new = []
    for j in nxt:
        t = _targets(world, tagged["segments"][j])
        if t is None:
            return False
        new += t
    all_t = np.array([*cur["targets"], *new]).reshape(-1, 2)
    return parking_pose(rect, all_t, yaw)[1]


def select_bench_stance(tagged, world, task_cfg, cfg=BENCH_RECT_CFG, full_check=None, points=None, say=print):
    """Chooses the parking spot of the plan's first run (see the module docstring).

    Args:
        tagged (dict): The tagged plan (src/mpvi_postprocess.postprocess).
        world (WorldModel): Filled (the config source is enough).
        task_cfg (dict): TASK_CFG: the heading (staging_yaw) that faces the bench and the pedestal command.
        cfg (dict): BENCH_RECT_CFG.
        full_check (FullCheck or None): The safety net (src/full_check.FullCheck). None: not run (the report says so).
        points (list or None): The task points for the full check (full_check.task_points(...)). Required with full_check.
        say (callable): Progress lines.

    Returns:
        dict: "ok", "task_cfg" (a copy with the chosen spot, or the original), "plan" (a copy of the tagged plan with end_at_zombie flags), "report".
    """
    rect = cfg["rectangle"]
    if rect is None:
        raise ValueError("BENCH_RECT_CFG['rectangle'] is not measured yet (experiments/bench_rectangle_measure.py)")
    yaw, q = float(task_cfg["staging_yaw"]), float(task_cfg["pedestal_q"])
    runs = plan_runs(tagged, world, yaw, rect)
    rep = {"rectangle": rect, "runs": [{"nav": r["nav"], "steps": r["steps"], "targets": np.asarray(r["targets"]).tolist(), "pose": r["pose"], "fits": r["fits"]} for r in runs], "candidates": [], "notes": []}
    moving = [r for r in runs if r["nav"] and r["pose"] is not None]
    if not moving:
        rep["notes"].append("no navigation step with resolvable targets: the stance stays as in TASK_CFG")
        return {"ok": False, "task_cfg": task_cfg, "plan": tagged, "report": rep}
    first = moving[0]
    if not first["fits"]:
        rep["notes"].append("the first run's targets do not fit in the rectangle from one spot")
        return {"ok": False, "task_cfg": task_cfg, "plan": tagged, "report": rep}
    if len(moving) > 1:
        rep["notes"].append("second stance not supported by the scripted staging: only the first run is parked")
    x0, y0, _ = first["pose"]
    c, s = math.cos(yaw), math.sin(yaw)
    fwd, left = np.array([c, s]), np.array([-s, c])
    shifts = [(0.0, 0.0), (0.0, cfg["shift_along_m"]), (0.0, -cfg["shift_along_m"]), (cfg["shift_across_m"], 0.0), (-cfg["shift_across_m"], 0.0)][: 1 + cfg["max_shifts"]]
    chosen = None
    for df, dl in shifts:                                     # along the bench = the base frame's left; toward/away = its forward
        xy = np.array([x0, y0]) + df * fwd + dl * left
        if not fits(rect, (xy[0], xy[1], yaw), first["targets"]):
            rep["candidates"].append({"xy": xy.tolist(), "shift": (df, dl), "skipped": "targets leave the rectangle"})
            continue
        cand = {"xy": xy.tolist(), "shift": (df, dl)}
        if full_check is not None:
            r = full_check.check((float(xy[0]), float(xy[1]), yaw, q), points)
            cand.update(full_check_ok=bool(r["ok"]), reason=r["reason"][:200], seconds=sum(r["seconds"].values()) if isinstance(r.get("seconds"), dict) else None)
        else:
            cand.update(full_check_ok=None)
        rep["candidates"].append(cand)
        say(f"[stance] candidate {np.round(xy, 3).tolist()} shift {(df, dl)}: full check {cand['full_check_ok']}")
        if full_check is None or cand["full_check_ok"]:
            chosen = xy
            break
    if chosen is None:
        rep["notes"].append("no candidate passed the full check (the first spot and the shifted spots): stop and report")
        return {"ok": False, "task_cfg": task_cfg, "plan": tagged, "report": rep}
    cfg2 = dict(task_cfg, staging_xy=(float(chosen[0]), float(chosen[1])), staging_yaw=yaw)
    plan2 = copy.deepcopy(tagged)
    for k, run in enumerate(runs):                            # M074: a pick returns to the zombie pose unless the next step is null
        for j in run["steps"]:
            seg = plan2["segments"][j]
            nxt = plan2["segments"][j + 1] if j + 1 < len(plan2["segments"]) else None
            if seg.get("primitive") == "pick" and nxt is not None and nxt["type"] == "navigation" and any(nxt["index"] == nr["nav"][0] for nr in runs if nr["nav"]):
                seg["end_at_zombie"] = True
    rep["chosen"] = {"xy": chosen.tolist(), "yaw": yaw, "pedestal_q": q, "task_cfg_xy": list(task_cfg["staging_xy"])}
    rep["null_nav"] = [n for r in runs for n in r["nav"][1:]]
    return {"ok": True, "task_cfg": cfg2, "plan": plan2, "report": rep}
